            "url": "https://mateuslucena.substack.com/p/evitando-armadilhas-em-conversas",
            "image": "https://substackcdn.com/image/fetch/$s_!mlnH!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fba1fd3b7-7476-45fd-ad4e-5baf1f8f43b6_750x750.jpeg",
