            "url": "https://mateuslucena.substack.com/p/relatorios-de-p-and-d-e-a-jornada",
            "image": "https://substack-post-media.s3.amazonaws.com/public/images/7be64088-b5a4-4e33-b869-0c24f2ae2fe2_1536x1024.png",
